fn get_name(case: usize, node: usize) -> String {
    format!("c{case:02}_n{node}_get")
}

fn visit_name(case: usize, node: usize) -> String {
    format!("c{case:02}_n{node}_visit")
}

fn static_name(case: usize, node: usize) -> String {
    format!("C{case:02}N{node}Static")
}
